<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class StoreTrainingProgramItemRequest extends FormRequest{public function authorize(){return$this->user()?->can('capacitaciones.programa.editar')??false;}public function rules(){return['training_topic_id'=>'nullable|exists:training_topics,id','title'=>'required|string|max:255','description'=>'nullable|string|max:4000','training_type'=>['required',Rule::in(array_keys(config('training.training_types')))],'planned_month'=>'required|integer|min:1|max:12','planned_date'=>'nullable|date','target_population_type'=>['required',Rule::in(array_keys(config('training.population_types')))],'target_population_description'=>'required|string|max:2000','responsible_employee_id'=>'nullable|exists:empleados,id','external_responsible'=>'nullable|required_without:responsible_employee_id|string|max:255','estimated_duration_minutes'=>'nullable|integer|min:1','planned_modality'=>['required',Rule::in(array_keys(config('training.modalities')))],'priority'=>'required|in:low,medium,high,critical','annual_work_plan_item_id'=>'nullable|exists:actividades_plan,id','need_ids'=>'required|array|min:1','need_ids.*'=>'exists:training_needs,id'];}public function attributes(){return['training_topic_id'=>'tema de capacitación','title'=>'actividad','description'=>'descripción','training_type'=>'tipo de capacitación','planned_month'=>'mes programado','planned_date'=>'fecha programada','target_population_type'=>'tipo de población','target_population_description'=>'población objetivo','responsible_employee_id'=>'responsable interno','external_responsible'=>'responsable externo','estimated_duration_minutes'=>'duración estimada','planned_modality'=>'modalidad','priority'=>'prioridad','annual_work_plan_item_id'=>'actividad del Plan Anual','need_ids'=>'necesidades atendidas','need_ids.*'=>'necesidad atendida'];}}
